export function normalizeHeaderValue(name, value) {
    if (!value.includes('\n')) {
        return value;
    }
    return value
        .split('\n')
        .map(v => {
        return v.trim();
    })
        .filter(Boolean)
        .join(name === 'set-cookie' ? '\n ' : ', ');
}